#include <bits/stdc++.h>
#define int long long
using namespace std;int N;vector<vector<pair<int,int>>>G;bool U[200001];int D[200001];bool f(int m){memset(U,false,sizeof(U));memset(D,0,sizeof(D));long long mn=LLONG_MAX,M=0;int c=0;for(int i=1;i<=N;i++){for(auto &r:G[i])if(r.second>m)D[i]++;}for(int i=1;i<=N;i++){if(!U[i]&&D[i]>0){c++;if(c>1)return false;queue<int>q;q.push(i);U[i]=true;while(!q.empty()){int h=q.front();q.pop();for(auto &w:G[h]){if(w.second>m){mn=min(mn,(long long)w.second);M=max(M,(long long)w.second);int y=w.first;if(!U[y]){U[y]=true;q.push(y);}}}}}}if(c==0)return true;for(int i=1;i<=N;i++){if(D[i]>2)return false;}return mn>=M-m;}void solve(){cin>>N;G.clear();G.resize(N+1);long long mx=0;for(int i=0;i<N-1;i++){int a,b,w;cin>>a>>b>>w;G[a].push_back({b,w});G[b].push_back({a,w});mx=max(mx,w);}long long L=0,R=mx,A=mx;while(L<=R){long long m=(L+R)/2;if(f(m)){A=m;R=m-1;}else L=m+1;}cout<<A<<"\n";}int32_t main(){ios_base::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--)solve();return 0;}
